type SettingValue =
  | {
      kind: "boolean";
      value: boolean;
    }
  | {
      kind: "integer";
      value: number;
    }
  | {
      kind: "string";
      value: string;
    };

type SettingOutcome =
  | {
      ok: true;
      key: string;
      value: SettingValue;
    }
  | {
      ok: false;
      key: string;
      reason: "empty";
    };

function assertNever(value: never): never {
  throw new Error(`Unhandled setting value kind: ${String(value)}`);
}

export function parseSetting(key: string, raw: string): SettingOutcome {
  if (raw.length === 0) {
    return {
      ok: false,
      key,
      reason: "empty",
    };
  }

  if (raw === "true" || raw === "false") {
    return {
      ok: true,
      key,
      value: {
        kind: "boolean",
        value: raw === "true",
      },
    };
  }

  if (/^-?\d+$/.test(raw)) {
    return {
      ok: true,
      key,
      value: {
        kind: "integer",
        value: Number(raw),
      },
    };
  }

  return {
    ok: true,
    key,
    value: {
      kind: "string",
      value: raw,
    },
  };
}

export function renderSetting(outcome: SettingOutcome): string {
  if (!outcome.ok) {
    return `${outcome.key}=!${outcome.reason}`;
  }

  const { key, value } = outcome;

  switch (value.kind) {
    case "boolean":
      return `${key}=${value.value}`;
    case "integer":
      return `${key}=${value.value}`;
    case "string":
      return `${key}=${value.value}`;
    default:
      return assertNever(value);
  }
}

