package solution

import (
	"errors"
	"sync"
)

func ProcessBatches(items []int, batchSize int, fn func([]int) (int, error)) ([]int, error) {
	if batchSize <= 0 || len(items) == 0 {
		return []int{}, nil
	}

	batchCount := (len(items) + batchSize - 1) / batchSize
	results := make([]int, batchCount)
	errs := make([]error, batchCount)

	var wg sync.WaitGroup
	wg.Add(batchCount)

	for i := 0; i < batchCount; i++ {
		start := i * batchSize
		end := start + batchSize
		if end > len(items) {
			end = len(items)
		}

		batch := items[start:end]
		go func(index int, batch []int) {
			defer wg.Done()

			result, err := fn(batch)
			if err != nil {
				errs[index] = err
				return
			}
			results[index] = result
		}(i, batch)
	}

	wg.Wait()

	return results, errors.Join(errs...)
}

