prompt:
Write a self-contained C++23 header `solution.hpp` (standard library only)
implementing a fixed-capacity least-recently-used cache.

```cpp
template <typename Key, typename Value>
class LruCache {
public:
    explicit LruCache(std::size_t capacity);

    // Insert or overwrite. The key becomes most recently used. When the cache
    // is full, the least recently used entry is evicted first.
    void put(const Key& key, const Value& value);

    // Returns the value and marks the key most recently used, or std::nullopt.
    std::optional<Value> get(const Key& key);

    // True if present. Does not change recency.
    bool contains(const Key& key) const;

    std::size_t size() const;
    std::size_t capacity() const;
};
```

Behaviour:

1. `put` and `get` are O(1) average.
2. Capacity 0 stores nothing: `put` is a no-op and `size()` stays 0.
3. Keys need only be hashable and equality-comparable (usable as an
   `std::unordered_map` key). Values are copyable.
4. The header must compile with `-std=c++23 -Wall -Wextra` and run clean
   under AddressSanitizer and UndefinedBehaviorSanitizer.

Return only the contents of `solution.hpp` in a single C++ code block.

code:
#pragma once

#include <cstddef>
#include <list>
#include <optional>
#include <unordered_map>

template <typename Key, typename Value>
class LruCache {
private:
    struct Entry {
        Key key;
        Value value;

        Entry(const Key& key_value, const Value& value_value)
            : key(key_value), value(value_value) {}
    };

    using EntryList = std::list<Entry>;
    using EntryIterator = typename EntryList::iterator;

    std::size_t capacity_;
    EntryList entries_;
    std::unordered_map<Key, EntryIterator> index_;

    void evict_least_recently_used() {
        auto victim = entries_.begin();
        index_.erase(victim->key);
        entries_.pop_front();
    }

public:
    explicit LruCache(std::size_t capacity)
        : capacity_(capacity) {}

    void put(const Key& key, const Value& value) {
        if (capacity_ == 0) {
            return;
        }

        auto existing = index_.find(key);
        if (existing != index_.end()) {
            existing->second->value = value;
            entries_.splice(entries_.end(), entries_, existing->second);
            return;
        }

        if (entries_.size() == capacity_) {
            evict_least_recently_used();
        }

        entries_.emplace_back(key, value);
        auto entry = entries_.end();
        --entry;

        try {
            const auto [map_entry, inserted] = index_.emplace(entry->key, entry);
            if (!inserted) {
                entries_.erase(entry);
            }
        } catch (...) {
            entries_.erase(entry);
            throw;
        }
    }

    std::optional<Value> get(const Key& key) {
        auto found = index_.find(key);
        if (found == index_.end()) {
            return std::nullopt;
        }

        std::optional<Value> result(found->second->value);
        entries_.splice(entries_.end(), entries_, found->second);
        return result;
    }

    bool contains(const Key& key) const {
        return index_.find(key) != index_.end();
    }

    std::size_t size() const {
        return entries_.size();
    }

    std::size_t capacity() const {
        return capacity_;
    }
};

