type SettingValue =
  | { readonly kind: "boolean"; readonly value: boolean }
  | { readonly kind: "integer"; readonly value: number }
  | { readonly kind: "string"; readonly value: string };

type ParseOutcome =
  | {
      readonly kind: "success";
      readonly key: string;
      readonly value: SettingValue;
    }
  | {
      readonly kind: "failure";
      readonly key: string;
      readonly reason: "empty";
    };

function assertNever(value: never): never {
  throw new Error(`Unhandled setting variant: ${String(value)}`);
}

export function parseSetting(key: string, raw: string): ParseOutcome {
  if (raw.length === 0) {
    return { kind: "failure", key, reason: "empty" };
  }

  if (raw === "true" || raw === "false") {
    return {
      kind: "success",
      key,
      value: { kind: "boolean", value: raw === "true" },
    };
  }

  if (/^-?\d+$/.test(raw)) {
    return {
      kind: "success",
      key,
      value: { kind: "integer", value: Number(raw) },
    };
  }

  return {
    kind: "success",
    key,
    value: { kind: "string", value: raw },
  };
}

export function renderSetting(outcome: ParseOutcome): string {
  switch (outcome.kind) {
    case "failure":
      return `${outcome.key}=!${outcome.reason}`;

    case "success": {
      let value: string;

      switch (outcome.value.kind) {
        case "boolean":
          value = String(outcome.value.value);
          break;
        case "integer":
          value = String(outcome.value.value);
          break;
        case "string":
          value = outcome.value.value;
          break;
        default:
          return assertNever(outcome.value);
      }

      return `${outcome.key}=${value}`;
    }

    default:
      return assertNever(outcome);
  }
}

