package solution

import (
	"errors"
	"sync"
)

func ProcessBatches(items []int, batchSize int, fn func([]int) (int, error)) ([]int, error) {
	if batchSize <= 0 || len(items) == 0 {
		return []int{}, nil
	}

	batchCount := (len(items)-1)/batchSize + 1
	results := make([]int, batchCount)
	batchErrors := make([]error, batchCount)

	var wg sync.WaitGroup
	for i := range batchCount {
		start := i * batchSize
		end := start + min(batchSize, len(items)-start)
		batch := items[start:end]

		wg.Go(func() {
			results[i], batchErrors[i] = fn(batch)
		})
	}

	wg.Wait()
	return results, errors.Join(batchErrors...)
}

