Write a self-contained C# file `Solution.cs` for .NET 10 (no NuGet packages,
nullable reference types enabled) that parses order lines.

Each non-empty line of the input is `id;quantity;unitPrice`. Whitespace around
a field is trimmed. `id` is a non-empty token, `quantity` a positive integer,
`unitPrice` a non-negative decimal written with `.` as the separator
regardless of the machine's culture.

Expose exactly these public members. Whether each type is a class, record or
struct is up to you.

```csharp
public static class OrderParser
{
    public static OrderParseResult Parse(string input);
}

// OrderParseResult:
//   bool IsSuccess
//   IReadOnlyList<Order> Orders   -- empty when IsSuccess is false
//   string? Error                 -- null when IsSuccess is true
//   int ErrorLine                 -- 1-based line of the first invalid line, 0 on success

// Order:
//   string Id
//   int Quantity
//   decimal UnitPrice
//   decimal Total                 -- Quantity * UnitPrice
```

Behaviour:

1. The first invalid line stops parsing. Blank lines are skipped but still
   count toward line numbers.
2. Empty input is a success with zero orders.

Return only the contents of `Solution.cs` in a single C# code block.

code:
#nullable enable

using System;
using System.Collections.Generic;
using System.Globalization;


/// <summary>
/// Parses order lines into validated orders.
/// </summary>
public static class OrderParser
{
    /// <summary>
    /// Parses the supplied order lines.
    /// </summary>
    /// <param name="input">The input containing zero or more order lines.</param>
    /// <returns>The parsing result.</returns>
    public static OrderParseResult Parse(string input)
    {
        ArgumentNullException.ThrowIfNull(input);

        var orders = new List<Order>();
        var lines = input.Split(new[] { "\r\n", "\n", "\r" }, StringSplitOptions.None);

        for (var index = 0; index < lines.Length; index++)
        {
            var lineNumber = index + 1;
            var line = lines[index];

            if (string.IsNullOrWhiteSpace(line))
            {
                continue;
            }

            var fields = line.Split(';');
            if (fields.Length != 3)
            {
                return Failure(lineNumber, "An order line must contain exactly three fields.");
            }

            var id = fields[0].Trim();
            if (id.Length == 0)
            {
                return Failure(lineNumber, "The order id must not be empty.");
            }

            var quantityText = fields[1].Trim();
            if (!TryParsePositiveInteger(quantityText, out var quantity))
            {
                return Failure(lineNumber, "The quantity must be a positive integer.");
            }

            var unitPriceText = fields[2].Trim();
            if (!TryParseUnitPrice(unitPriceText, out var unitPrice))
            {
                return Failure(lineNumber, "The unit price must be a non-negative decimal using '.' as the separator.");
            }

            decimal total;
            try
            {
                total = quantity * unitPrice;
            }
            catch (OverflowException)
            {
                return Failure(lineNumber, "The order total exceeds the supported decimal range.");
            }

            orders.Add(new Order(id, quantity, unitPrice, total));
        }

        return new OrderParseResult(
            isSuccess: true,
            orders: orders.AsReadOnly(),
            error: null,
            errorLine: 0);
    }

    private static bool TryParsePositiveInteger(string value, out int result)
    {
        result = 0;

        if (value.Length == 0)
        {
            return false;
        }

        foreach (var character in value)
        {
            if (character is < '0' or > '9')
            {
                return false;
            }
        }

        return int.TryParse(
                   value,
                   NumberStyles.None,
                   CultureInfo.InvariantCulture,
                   out result)
               && result > 0;
    }

    private static bool TryParseUnitPrice(string value, out decimal result)
    {
        result = 0m;

        if (value.Length == 0)
        {
            return false;
        }

        var hasDecimalPoint = false;
        var hasDigit = false;

        foreach (var character in value)
        {
            if (character is >= '0' and <= '9')
            {
                hasDigit = true;
                continue;
            }

            if (character == '.' && !hasDecimalPoint)
            {
                hasDecimalPoint = true;
                continue;
            }

            return false;
        }

        return hasDigit
            && decimal.TryParse(
                value,
                NumberStyles.AllowDecimalPoint,
                CultureInfo.InvariantCulture,
                out result)
            && result >= 0m;
    }

    private static OrderParseResult Failure(int lineNumber, string message) =>
        new(
            isSuccess: false,
            orders: Array.Empty<Order>(),
            error: $"Line {lineNumber}: {message}",
            errorLine: lineNumber);
}

/// <summary>
/// Represents the result of parsing order lines.
/// </summary>
public sealed class OrderParseResult
