type SettingOutcome =
  | { kind: "boolean"; key: string; value: boolean }
  | { kind: "integer"; key: string; value: number }
  | { kind: "string"; key: string; value: string }
  | { kind: "failure"; key: string; reason: "empty" };

function assertNever(value: never): never {
  throw new Error(`Unhandled setting outcome: ${String(value)}`);
}

export function parseSetting(key: string, raw: string): SettingOutcome {
  if (raw === "") {
    return { kind: "failure", key, reason: "empty" };
  }

  if (raw === "true" || raw === "false") {
    return { kind: "boolean", key, value: raw === "true" };
  }

  if (/^-?\d+$/.test(raw)) {
    return { kind: "integer", key, value: Number(raw) };
  }

  return { kind: "string", key, value: raw };
}

export function renderSetting(outcome: SettingOutcome): string {
  switch (outcome.kind) {
    case "boolean":
      return `${outcome.key}=${outcome.value}`;

    case "integer":
      return `${outcome.key}=${outcome.value}`;

    case "string":
      return `${outcome.key}=${outcome.value}`;

    case "failure":
      return `${outcome.key}=!${outcome.reason}`;

    default:
      return assertNever(outcome);
  }
}

