package solution

import (
	"errors"
	"sync"
)

func ProcessBatches(items []int, batchSize int, fn func([]int) (int, error)) ([]int, error) {
	if batchSize <= 0 || len(items) == 0 {
		return []int{}, nil
	}

	batchCount := (len(items) + batchSize - 1) / batchSize
	results := make([]int, batchCount)
	errs := make([]error, batchCount)

	var wg sync.WaitGroup
	wg.Add(batchCount)

	for i := 0; i < batchCount; i++ {
		start := i * batchSize
		end := start + batchSize
		if end > len(items) {
			end = len(items)
		}

		go func(index, start, end int) {
			defer wg.Done()
			results[index], errs[index] = fn(items[start:end])
		}(i, start, end)
	}

	wg.Wait()

	return results, errors.Join(errs...)
}

