use std::error::Error;
use std::fmt;

pub struct Record {
    name: String,
    age: u8,
    email: String,
}

impl Record {
    pub fn name(&self) -> &str {
        &self.name
    }

    pub fn age(&self) -> u8 {
        self.age
    }

    pub fn email(&self) -> &str {
        &self.email
    }
}

pub struct ParseError {
    line: usize,
    message: &'static str,
}

impl ParseError {
    pub fn line(&self) -> usize {
        self.line
    }
}

impl fmt::Debug for ParseError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ParseError")
            .field("line", &self.line)
            .field("message", &self.message)
            .finish()
    }
}

impl fmt::Display for ParseError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            formatter,
            "invalid record on line {}: {}",
            self.line, self.message
        )
    }
}

impl Error for ParseError {}

pub fn parse_records(input: &str) -> Result<Vec<Record>, ParseError> {
    let mut records = Vec::new();

    for (index, line) in input.lines().enumerate() {
        let line_number = index + 1;

        if line.trim().is_empty() {
            continue;
        }

        let fields: Vec<&str> = line.split(',').map(str::trim).collect();
        if fields.len() != 3 {
            return Err(ParseError {
                line: line_number,
                message: "expected exactly three fields",
            });
        }

        let name = fields[0];
        if name.is_empty() {
            return Err(ParseError {
                line: line_number,
                message: "name must not be empty",
            });
        }

        let age_value = match fields[1].parse::<u16>() {
            Ok(value) if value <= 150 => value as u8,
            _ => {
                return Err(ParseError {
                    line: line_number,
                    message: "age must be an integer from 0 through 150",
                });
            }
        };

        let mut email_parts = fields[2].split('@');
        let local = email_parts.next().unwrap_or("");
        let domain = email_parts.next().unwrap_or("");
        if local.is_empty() || domain.is_empty() || email_parts.next().is_some() {
            return Err(ParseError {
                line: line_number,
                message: "email must contain exactly one @ with non-empty sides",
            });
        }

        records.push(Record {
            name: name.to_owned(),
            age: age_value,
            email: fields[2].to_owned(),
        });
    }

    Ok(records)
}

