size_t
rle_encode(const unsigned char *in, size_t n, unsigned char *out, size_t cap)
{
    size_t i = 0;
    size_t total = 0;

    while (i < n) {
        const unsigned char value = in[i];
        size_t run = 1;

        while (run < 255 &&
               run < n - i &&
               in[i + run] == value) {
            ++run;
        }

        if (total > SIZE_MAX - 2) {
            return SIZE_MAX;
        }

        if (total < cap) {
            out[total] = (unsigned char)run;
        }
        if (total + 1 < cap) {
            out[total + 1] = value;
        }

        total += 2;
        i += run;
    }

    return total;
}

size_t
rle_decode(const unsigned char *in, size_t n, unsigned char *out, size_t cap)
{
    size_t i;
    size_t total = 0;

    if (n == 0) {
        return 0;
    }

    if (n % 2 != 0) {
        return SIZE_MAX;
    }

    for (i = 0; i < n; i += 2) {
        const size_t run = in[i];

        if (run == 0) {
            return SIZE_MAX;
        }
        if (total > SIZE_MAX - run) {
            return SIZE_MAX;
        }

        total += run;
    }

    {
        size_t written = 0;

        for (i = 0; i < n; i += 2) {
            const size_t run = in[i];
            const unsigned char value = in[i + 1];
            size_t j;

            for (j = 0; j < run; ++j) {
                if (written < cap) {
                    out[written] = value;
                }
                ++written;
            }
        }
    }

    return total;
}

