type SettingValue =
  | { readonly kind: "boolean"; readonly value: boolean }
  | { readonly kind: "integer"; readonly value: number }
  | { readonly kind: "string"; readonly value: string };

type ParseOutcome =
  | {
      readonly status: "success";
      readonly key: string;
      readonly value: SettingValue;
    }
  | {
      readonly status: "failure";
      readonly key: string;
      readonly reason: "empty";
    };

export function parseSetting(key: string, raw: string): ParseOutcome {
  if (raw.length === 0) {
    return {
      status: "failure",
      key,
      reason: "empty",
    };
  }

  if (raw === "true" || raw === "false") {
    return {
      status: "success",
      key,
      value: {
        kind: "boolean",
        value: raw === "true",
      },
    };
  }

  if (/^-?\d+$/.test(raw)) {
    return {
      status: "success",
      key,
      value: {
        kind: "integer",
        value: Number(raw),
      },
    };
  }

  return {
    status: "success",
    key,
    value: {
      kind: "string",
      value: raw,
    },
  };
}

export function renderSetting(outcome: ParseOutcome): string {
  if (outcome.status === "failure") {
    return `${outcome.key}=!${outcome.reason}`;
  }

  switch (outcome.value.kind) {
    case "boolean":
      return `${outcome.key}=${outcome.value.value}`;
    case "integer":
      return `${outcome.key}=${outcome.value.value}`;
    case "string":
      return `${outcome.key}=${outcome.value.value}`;
    default:
      return assertNever(outcome.value);
  }
}

function assertNever(value: never): never {
  throw new Error(`Unhandled setting value: ${String(value)}`);
}

