package solution

import (
	"errors"
	"sync"
)

func ProcessBatches(items []int, batchSize int, fn func([]int) (int, error)) ([]int, error) {
	if batchSize <= 0 || len(items) == 0 {
		return []int{}, nil
	}

	batchCount := (len(items)-1)/batchSize + 1
	results := make([]int, batchCount)
	errs := make([]error, batchCount)

	var wg sync.WaitGroup
	for start, batchIndex := 0, 0; start < len(items); batchIndex++ {
		end := len(items)
		if batchSize < end-start {
			end = start + batchSize
		}

		batch := items[start:end]
		index := batchIndex
		wg.Go(func() {
			results[index], errs[index] = fn(batch)
		})

		start = end
	}

	wg.Wait()
	return results, errors.Join(errs...)
}

