using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;

/// <summary>
/// Parses order lines into orders.
/// </summary>
public static class OrderParser
{
    /// <summary>
    /// Parses newline-separated order lines.
    /// </summary>
    /// <param name="input">The input containing order lines.</param>
    /// <returns>The parsing result.</returns>
    public static OrderParseResult Parse(string input)
    {
        ArgumentNullException.ThrowIfNull(input);

        var orders = new List<Order>();
        var lines = input.Split('\n');

        for (var index = 0; index < lines.Length; index++)
        {
            var lineNumber = index + 1;
            var line = lines[index].Trim();

            if (line.Length == 0)
            {
                continue;
            }

            var fields = line.Split(';');

            if (fields.Length != 3)
            {
                return OrderParseResult.Failure(
                    $"Line {lineNumber} must contain exactly three fields.",
                    lineNumber);
            }

            var id = fields[0].Trim();
            var quantityText = fields[1].Trim();
            var unitPriceText = fields[2].Trim();

            if (id.Length == 0)
            {
                return OrderParseResult.Failure(
                    $"Line {lineNumber} has an empty id.",
                    lineNumber);
            }

            if (!IsPositiveInteger(quantityText, out var quantity))
            {
                return OrderParseResult.Failure(
                    $"Line {lineNumber} has an invalid quantity.",
                    lineNumber);
            }

            if (!IsNonNegativeDecimal(unitPriceText, out var unitPrice))
            {
                return OrderParseResult.Failure(
                    $"Line {lineNumber} has an invalid unit price.",
                    lineNumber);
            }

            orders.Add(new Order(id, quantity, unitPrice));
        }

        return OrderParseResult.Success(orders);
    }

    private static bool IsPositiveInteger(string value, out int result)
    {
        return int.TryParse(
                   value,
                   NumberStyles.None,
                   CultureInfo.InvariantCulture,
                   out result)
               && result > 0;
    }

    private static bool IsNonNegativeDecimal(string value, out decimal result)
    {
        result = default;

        if (value.Length == 0)
        {
            return false;
        }

        var digitCount = 0;
        var decimalPointCount = 0;

        foreach (var character in value)
        {
            if (character is >= '0' and <= '9')
            {
                digitCount++;
                continue;
            }

            if (character == '.')
            {
                decimalPointCount++;

                if (decimalPointCount > 1)
                {
                    return false;
                }

                continue;
            }

            return false;
        }

        return digitCount > 0
               && decimal.TryParse(
                   value,
                   NumberStyles.AllowDecimalPoint,
                   CultureInfo.InvariantCulture,
                   out result)
               && result >= 0;
    }
