type SettingValue =
  | { kind: "boolean"; value: boolean }
  | { kind: "integer"; value: number }
  | { kind: "string"; value: string };

type SettingOutcome =
  | {
      status: "success";
      key: string;
      value: SettingValue;
    }
  | {
      status: "failure";
      key: string;
      reason: "empty";
    };

function assertNever(value: never): never {
  throw new Error(`Unhandled value: ${String(value)}`);
}

export function parseSetting(key: string, raw: string): SettingOutcome {
  if (raw.length === 0) {
    return {
      status: "failure",
      key,
      reason: "empty",
    };
  }

  if (raw === "true" || raw === "false") {
    return {
      status: "success",
      key,
      value: {
        kind: "boolean",
        value: raw === "true",
      },
    };
  }

  if (/^-?\d+$/.test(raw)) {
    return {
      status: "success",
      key,
      value: {
        kind: "integer",
        value: Number(raw),
      },
    };
  }

  return {
    status: "success",
    key,
    value: {
      kind: "string",
      value: raw,
    },
  };
}

export function renderSetting(outcome: SettingOutcome): string {
  switch (outcome.status) {
    case "failure":
      return `${outcome.key}=!${outcome.reason}`;

    case "success": {
      let value: string;

      switch (outcome.value.kind) {
        case "boolean":
          value = String(outcome.value.value);
          break;
        case "integer":
          value = String(outcome.value.value);
          break;
        case "string":
          value = outcome.value.value;
          break;
        default:
          return assertNever(outcome.value);
      }

      return `${outcome.key}=${value}`;
    }

    default:
      return assertNever(outcome);
  }
}

