package solution

import (
	"errors"
	"sync"
)

func ProcessBatches(items []int, batchSize int, fn func([]int) (int, error)) ([]int, error) {
	if batchSize <= 0 || len(items) == 0 {
		return []int{}, nil
	}

	batchCount := (len(items) + batchSize - 1) / batchSize
	results := make([]int, batchCount)
	errs := make([]error, batchCount)

	var wg sync.WaitGroup
	wg.Add(batchCount)

	for i, start := 0, 0; i < batchCount; i++ {
		end := len(items)
		if remaining := len(items) - start; remaining > batchSize {
			end = start + batchSize
		}

		batch := items[start:end]
		index := i
		start = end

		go func() {
			defer wg.Done()
			results[index], errs[index] = fn(batch)
		}()
	}

	wg.Wait()

	var batchErrors []error
	for _, err := range errs {
		if err != nil {
			batchErrors = append(batchErrors, err)
		}
	}

	return results, errors.Join(batchErrors...)
}

