use std::fmt;

pub struct Record {
    name: String,
    age: u8,
    email: String,
}

impl Record {
    pub fn name(&self) -> &str {
        &self.name
    }

    pub fn age(&self) -> u8 {
        self.age
    }

    pub fn email(&self) -> &str {
        &self.email
    }
}

#[derive(Debug)]
pub struct ParseError {
    line: usize,
}

impl ParseError {
    pub fn line(&self) -> usize {
        self.line
    }
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "invalid record on line {}", self.line)
    }
}

impl std::error::Error for ParseError {}

pub fn parse_records(input: &str) -> Result<Vec<Record>, ParseError> {
    let mut records = Vec::new();

    for (index, line) in input.lines().enumerate() {
        let line_number = index + 1;

        if line.trim().is_empty() {
            continue;
        }

        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() != 3 {
            return Err(ParseError { line: line_number });
        }

        let name = fields[0].trim();
        let age_text = fields[1].trim();
        let email = fields[2].trim();

        if name.is_empty() {
            return Err(ParseError { line: line_number });
        }

        let age_value = match age_text.parse::<i64>() {
            Ok(value) if (0..=150).contains(&value) => value as u8,
            _ => return Err(ParseError { line: line_number }),
        };

        let (local, domain) = match email.split_once('@') {
            Some(parts) if !parts.0.is_empty() && !parts.1.is_empty() => parts,
            _ => return Err(ParseError { line: line_number }),
        };

        if domain.contains('@') {
            return Err(ParseError { line: line_number });
        }

        records.push(Record {
            name: name.to_owned(),
            age: age_value,
            email: format!("{local}@{domain}"),
        });
    }

    Ok(records)
}

