using System;
using System.Collections.Generic;
using System.Globalization;

public static class OrderParser
{
    public static OrderParseResult Parse(string input)
    {
        if (input is null)
        {
            throw new ArgumentNullException(nameof(input));
        }

        var orders = new List<Order>();
        var lines = input.Split('\n');

        for (var index = 0; index < lines.Length; index++)
        {
            var lineNumber = index + 1;
            var line = lines[index].Trim();

            if (line.Length == 0)
            {
                continue;
            }

            var fields = line.Split(';');
            if (fields.Length != 3)
            {
                return Failure(lineNumber);
            }

            var id = fields[0].Trim();
            var quantityText = fields[1].Trim();
            var unitPriceText = fields[2].Trim();

            if (id.Length == 0 ||
                !int.TryParse(
                    quantityText,
                    NumberStyles.None,
                    CultureInfo.InvariantCulture,
                    out var quantity) ||
                quantity <= 0 ||
                !decimal.TryParse(
                    unitPriceText,
                    NumberStyles.AllowDecimalPoint,
                    CultureInfo.InvariantCulture,
                    out var unitPrice) ||
                unitPrice < 0)
            {
                return Failure(lineNumber);
            }

            try
            {
                orders.Add(new Order(id, quantity, unitPrice));
            }
            catch (OverflowException)
            {
                return Failure(lineNumber);
            }
        }

        return new OrderParseResult(
            true,
            Array.AsReadOnly(orders.ToArray()),
            null,
            0);
    }

    private static OrderParseResult Failure(int lineNumber)
    {
        return new OrderParseResult(
            false,
            Array.Empty<Order>(),
            "Invalid order line.",
            lineNumber);
    }
}

