#include <stddef.h>
#include <stdint.h>

size_t rle_encode(const unsigned char *in, size_t n,
                  unsigned char *out, size_t cap);

size_t rle_decode(const unsigned char *in, size_t n,
                  unsigned char *out, size_t cap);

size_t
rle_encode(const unsigned char *in, size_t n,
           unsigned char *out, size_t cap)
{
    size_t i = 0;
    size_t total = 0;

    while (i < n) {
        const unsigned char value = in[i];
        size_t run = 1;

        while (run < 255 &&
               run < n - i &&
               in[i + run] == value) {
            ++run;
        }

        if (out != NULL && total < cap) {
            out[total] = (unsigned char)run;
        }
        ++total;

        if (out != NULL && total < cap) {
            out[total] = value;
        }
        ++total;

        i += run;
    }

    return total;
}

size_t
rle_decode(const unsigned char *in, size_t n,
           unsigned char *out, size_t cap)
{
    size_t i;
    size_t total = 0;

    if ((n & 1u) != 0) {
        return SIZE_MAX;
    }

    for (i = 0; i < n; i += 2) {
        const unsigned char run = in[i];
        const unsigned char value = in[i + 1];
        size_t j;

        if (run == 0) {
            return SIZE_MAX;
        }

        for (j = 0; j < (size_t)run; ++j) {
            if (out != NULL && total < cap) {
                out[total] = value;
            }
            ++total;
        }
    }

    return total;
}

