package solution

import (
	"errors"
	"sync"
)

func ProcessBatches(items []int, batchSize int, fn func([]int) (int, error)) ([]int, error) {
	if batchSize <= 0 || len(items) == 0 {
		return []int{}, nil
	}

	batchCount := (len(items)-1)/batchSize + 1
	results := make([]int, batchCount)
	batchErrors := make([]error, batchCount)

	var wg sync.WaitGroup
	for batchIndex := range batchCount {
		start := batchIndex * batchSize
		end := min(start+batchSize, len(items))
		batch := items[start:end]

		wg.Go(func() {
			result, err := fn(batch)
			if err != nil {
				batchErrors[batchIndex] = err
				return
			}
			results[batchIndex] = result
		})
	}
	wg.Wait()

	return results, errors.Join(batchErrors...)
}

