        self.age
    }

    pub fn email(&self) -> &str {
        &self.email
    }
}

pub struct ParseError {
    line: usize,
    reason: &'static str,
}

impl ParseError {
    pub fn line(&self) -> usize {
        self.line
    }
}

impl fmt::Debug for ParseError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ParseError")
            .field("line", &self.line)
            .field("reason", &self.reason)
            .finish()
    }
}

impl fmt::Display for ParseError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(formatter, "invalid record on line {}: {}", self.line, self.reason)
    }
}

impl Error for ParseError {}

pub fn parse_records(input: &str) -> Result<Vec<Record>, ParseError> {
    let mut records = Vec::new();

    for (index, line) in input.lines().enumerate() {
        let line_number = index + 1;
        let line = line.trim();

        if line.is_empty() {
            continue;
        }

        let fields: Vec<&str> = line.split(',').map(str::trim).collect();
        if fields.len() != 3 {
            return Err(ParseError {
                line: line_number,
                reason: "expected exactly three fields",
            });
        }

        let name = fields[0];
        if name.is_empty() {
            return Err(ParseError {
                line: line_number,
                reason: "name must not be empty",
            });
        }

        let age = match fields[1].parse::<u16>() {
            Ok(age) if age <= 150 => age as u8,
            _ => {
                return Err(ParseError {
                    line: line_number,
                    reason: "age must be an integer from 0 through 150",
                });
            }
        };

        let email = fields[2];
        let mut email_parts = email.split('@');
        let local = email_parts.next().unwrap_or_default();
        let domain = email_parts.next().unwrap_or_default();

        if local.is_empty() || domain.is_empty() || email_parts.next().is_some() {
            return Err(ParseError {
                line: line_number,
                reason: "email must contain exactly one @ with non-empty sides",
            });
        }

        records.push(Record {
            name: name.to_owned(),
            age,
            email: email.to_owned(),
        });
    }

    Ok(records)
}
