Write a self-contained C# file `Solution.cs` for .NET 10 (no NuGet packages,
nullable reference types enabled) that parses order lines.

Each non-empty line of the input is `id;quantity;unitPrice`. Whitespace around
a field is trimmed. `id` is a non-empty token, `quantity` a positive integer,
`unitPrice` a non-negative decimal written with `.` as the separator
regardless of the machine's culture.

Expose exactly these public members. Whether each type is a class, record or
struct is up to you.

```csharp
public static class OrderParser
{
    public static OrderParseResult Parse(string input);
}

// OrderParseResult:
//   bool IsSuccess
//   IReadOnlyList<Order> Orders   -- empty when IsSuccess is false
//   string? Error                 -- null when IsSuccess is true
//   int ErrorLine                 -- 1-based line of the first invalid line, 0 on success

// Order:
//   string Id
//   int Quantity
//   decimal UnitPrice
//   decimal Total                 -- Quantity * UnitPrice
```

Behaviour:

1. The first invalid line stops parsing. Blank lines are skipped but still
   count toward line numbers.
2. Empty input is a success with zero orders.

Return only the contents of `Solution.cs` in a single C# code block.

code:
#nullable enable

using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Globalization;
using System.IO;

public static class OrderParser
{
    public static OrderParseResult Parse(string input)
    {
        ArgumentNullException.ThrowIfNull(input);

        var orders = new List<Order>();
        using var reader = new StringReader(input);

        var lineNumber = 0;
        string? line;

        while ((line = reader.ReadLine()) is not null)
        {
            lineNumber++;

            if (string.IsNullOrWhiteSpace(line))
            {
                continue;
            }

            var fields = line.Split(';');

            if (fields.Length != 3)
            {
                return Failure(lineNumber, "The line must contain exactly three fields.");
            }

            var id = fields[0].Trim();
            var quantityText = fields[1].Trim();
            var unitPriceText = fields[2].Trim();

            if (id.Length == 0)
            {
                return Failure(lineNumber, "The order id must not be empty.");
            }

            if (!int.TryParse(
                    quantityText,
                    NumberStyles.None,
                    CultureInfo.InvariantCulture,
                    out var quantity) ||
                quantity <= 0)
            {
                return Failure(lineNumber, "The quantity must be a positive integer.");
            }

            if (!decimal.TryParse(
                    unitPriceText,
                    NumberStyles.AllowDecimalPoint,
                    CultureInfo.InvariantCulture,
                    out var unitPrice) ||
                unitPrice < 0)
            {
                return Failure(lineNumber, "The unit price must be a non-negative decimal.");
            }

            decimal total;

            try
            {
                total = quantity * unitPrice;
            }
            catch (OverflowException)
            {
                return Failure(lineNumber, "The order total is outside the supported decimal range.");
            }

            orders.Add(new Order(id, quantity, unitPrice, total));
        }

        return new OrderParseResult(
            true,
            new ReadOnlyCollection<Order>(orders),
            null,
            0);
    }

    private static OrderParseResult Failure(int lineNumber, string error) =>
        new(
            false,
            Array.Empty<Order>(),
            error,
            lineNumber);
}

/// <summary>
/// Represents the result of parsing order lines.
/// </summary>
public sealed class OrderParseResult
{
    internal OrderParseResult(
        bool isSuccess,
        IReadOnlyList<Order> orders,
        string? error,
        int errorLine)
    {
        IsSuccess = isSuccess;
        Orders = orders;
        Error = error;
        ErrorLine = errorLine;
    }

    /// <summary>
    /// Gets a value indicating whether parsing succeeded.
    /// </summary>
    public bool IsSuccess { get; }

    /// <summary>
    /// Gets the parsed orders.
    /// </summary>
    public IReadOnlyList<Order> Orders { get; }

    /// <summary>
    /// Gets the parsing error, or <see langword="null"/> when parsing succeeded.
    /// </summary>
    public string? Error { get; }

    /// <summary>
    /// Gets the one-based line number of the first invalid line, or zero on success.
    /// </summary>
    public int ErrorLine { get; }
}

/// <summary>
/// Represents a parsed order.
/// </summary>
public sealed class Order
{
    internal Order(string id, int quantity, decimal unitPrice, decimal total)
    {
        Id = id;
        Quantity = quantity;
        UnitPrice = unitPrice;
        Total = total;
    }

    /// <summary>
    /// Gets the order identifier.
    /// </summary>
    public string Id { get; }

    /// <summary>
    /// Gets the ordered quantity.
    /// </summary>
    public int Quantity { get; }

    /// <summary>
    /// Gets the price per unit.
    /// </summary>
    public decimal UnitPrice { get; }

    /// <summary>
    /// Gets the total order price.
    /// </summary>
    public decimal Total { get; }
}

